struct string_buf
{
  int pad0;
  int pad4;
  int char_length;
};

class stringx
{
protected:
  char *chars;
  string_buf *my_buf;
public:
  inline const char operator[](int i) const
  {
    if (i < 0)
      i += length();
    return chars[i];
  }

  inline int size() const
  {
    return my_buf->char_length;
  }

  int length() const;
};

struct char_info
{
  int x0;
  int y0;
  int x1;
  int y1;
  int adv;
};

class typeface_def
{
  char_info char_infos[256];
  const char_info *get_char_info(int c) const { return &char_infos[c]; }
  int interkern(int l1, int l2) const;
public:
  int text_width(const stringx &s) const;
};

int typeface_def::text_width( const stringx &s ) const
{
  int w = 0;
  const char_info *ci;
  int ssize = s.size();

  for (int i=0 ; i<ssize; ++i)
  {
    if( s[i] == '\\' )
    {
      ++i;
      if (i>=ssize-1) break;
      if (s[i] == 'n') break;
      if (s[i] == 'c') { i += 9; }
      continue;
    }
    ci = get_char_info((unsigned char)(s[i]));
    if(ci)
    {
      w += ci->x1 - ci->x0 + 0 + ci->adv;
      if( i < ssize-1 )
      {
        w += interkern( s[i], s[i+1] );
      }
    }
  }
  return w;
}
